const compFrame = figma.getNodeById('1:18');
const mediaFrame = figma.getNodeById('6:59');

function getChildrenInfo(node, depth = 1) {
  if (depth <= 0 || !('children' in node)) return node.name;
  return {
    id: node.id,
    name: node.name,
    type: node.type,
    children: node.children.map(c => getChildrenInfo(c, depth - 1))
  };
}

return {
  components: compFrame ? getChildrenInfo(compFrame, 2) : null,
  media: mediaFrame ? getChildrenInfo(mediaFrame, 2) : null
};

