const mediaFrame = figma.getNodeById('6:59');
const assets = {};

function collectAssets(node) {
  if (node.type === 'FRAME' || node.type === 'GROUP' || node.type === 'COMPONENT' || node.type === 'INSTANCE' || node.type === 'VECTOR') {
    if (node.name.startsWith('Icon_') || node.name.startsWith('Avatar_') || node.name.startsWith('Photo_') || node.name.startsWith('Logo_')) {
      assets[node.name] = node.id;
    }
  }
  if ('children' in node) {
    for (const child of node.children) {
      collectAssets(child);
    }
  }
}

collectAssets(mediaFrame);
return assets;

async function buildDesign() {
  await figma.loadFontAsync({ family: "DM Sans", style: "Regular" });
  await figma.loadFontAsync({ family: "DM Sans", style: "Medium" });
  await figma.loadFontAsync({ family: "DM Sans", style: "Bold" });

  const workspace = figma.getNodeById('8:2');
  await figma.setCurrentPageAsync(workspace);

  // Clear workspace existing children
  for (const child of workspace.children) {
    child.remove();
  }

  return "Workspace cleared and fonts loaded successfully";
}

return await buildDesign();

