  // 7 points plotting
  const points = [67, 73, 53, 47, 39, 27, 27];
  // map values to y coordinates (min 27 -> y: 220, max 73 -> y: 60)
  const px = [20, 60, 100, 140, 180, 220, 260];
  const py = points.map(v => 240 - (v - 20) * 3);

  // Draw vector path connecting points
  const pathData = `M ${px[0]} ${py[0]} L ${px[1]} ${py[1]} L ${px[2]} ${py[2]} L ${px[3]} ${py[3]} L ${px[4]} ${py[4]} L ${px[5]} ${py[5]} L ${px[6]} ${py[6]}`;
