  points.forEach((val, idx) => {
    const isLast = idx === points.length - 1;
    const dot = figma.createEllipse();
    dot.resize(isLast ? 12 : 8, isLast ? 12 : 8);
    dot.x = px[idx] - (isLast ? 6 : 4);
    dot.y = py[idx] - (isLast ? 6 : 4);
    dot.fills = [{ type: 'SOLID', color: isLast ? { r: 0.314, g: 0.318, b: 0.976 } : { r: 0.6, g: 0.6, b: 0.7 } }];
    if (isLast) {
      dot.strokes = [{ type: 'SOLID', color: { r: 1, g: 1, b: 1 } }];
      dot.strokeWeight = 2;
    }
    chartBox.appendChild(dot);

    // Label for each point
    const pLbl = figma.createText();
    pLbl.characters = String(val);
    pLbl.fontName = { family: "DM Sans", style: isLast ? "Bold" : "Regular" };
    pLbl.fontSize = 11;
    pLbl.fills = [{ type: 'SOLID', color: isLast ? { r: 0.314, g: 0.318, b: 0.976 } : { r: 0.5, g: 0.5, b: 0.55 } }];
    pLbl.x = px[idx] - 8;
    pLbl.y = py[idx] - 22;
    chartBox.appendChild(pLbl);
  });

  completeCard.appendChild(chartBox);

  // Additional completion details summary
  const summaryBox = figma.createFrame();
