async function wirePrototypesCheck() {
  const workspace = figma.getNodeById('8:2');
  await figma.setCurrentPageAsync(workspace);

  const f1 = workspace.children.find(c => c.name === "01_Dashboard");
  const f2 = workspace.children.find(c => c.name === "02_Timeline");
  const f3 = workspace.children.find(c => c.name === "03_Task_Board");
  const f4 = workspace.children.find(c => c.name === "04_Files");
  const f5 = workspace.children.find(c => c.name === "05_Settings");
  const f6 = workspace.children.find(c => c.name === "06_Messages");

  const framesMap = {
    "Dashboard": f1,
    "Timeline": f2,
    "Task": f3,
    "Files": f4,
    "Settings": f5,
    "Messages": f6
  };

  const results = [];
  const allFrames = [f1, f2, f3, f4, f5, f6];

  for (const fr of allFrames) {
    const sidebar = fr.children.find(c => c.name === "Sidebar");
    if (!sidebar) {
      results.push(`No Sidebar in ${fr.name}`);
      continue;
    }

    const navGroup = sidebar.children.find(c => c.name === "NavGroup");
    if (!navGroup) {
      results.push(`No NavGroup in Sidebar of ${fr.name}`);
      continue;
    }

    const navItems = navGroup.children.find(c => c.name === "NavItems");
    if (!navItems) {
      results.push(`No NavItems in NavGroup of ${fr.name}`);
      continue;
    }

    for (const navBtn of navItems.children) {
      const key = navBtn.name.replace("Nav_", "");
      const targetFrame = framesMap[key];
      if (targetFrame) {
        if (targetFrame.id === fr.id) {
          // Skip self-navigation
          continue;
        }
        try {
          navBtn.reactions = [{
            actions: [{
              type: "NODE",
              destinationId: targetFrame.id,
              navigation: "NAVIGATE",
              transition: null
            }],
            trigger: { type: "ON_CLICK" }
          }];
          results.push(`Success ${fr.name} -> ${targetFrame.name}`);
        } catch (e) {
          results.push(`Failed ${fr.name} -> ${targetFrame.name}: ${e.message}`);
        }
      }
    }
  }

  // 01_Dashboard message row to 06_Messages
  const rightCol = f1.children.find(c => c.name === "Content")?.children.find(c => c.name === "RightCol");
  const msgCard = rightCol?.children.find(c => c.name === "MessagesCard");
  if (msgCard) {
    for (const child of msgCard.children) {
      if (child.name.startsWith("MessageRow_")) {
        try {
          child.reactions = [{
            actions: [{
              type: "NODE",
              destinationId: f6.id,
              navigation: "NAVIGATE",
              transition: null
            }],
            trigger: { type: "ON_CLICK" }
          }];
          results.push(`Success MessageRow -> ${f6.name}`);
        } catch (e) {
          results.push(`Failed MessageRow -> ${f6.name}: ${e.message}`);
        }
      }
    }
  }

  return results;
}

