function getStructure(node) {
  const info = { id: node.id, name: node.name, type: node.type };
  if ('children' in node) {
    info.children = node.children.map(c => getStructure(c));
  }
  return info;
}

const frames = ["02_Timeline", "03_Task_Board", "04_Files", "05_Settings", "06_Messages"];
const structures = {};

for (const fName of frames) {
  const fr = workspace.children.find(c => c.name === fName);
  if (fr) {
    const sidebar = fr.children.find(c => c.name === "Sidebar");
    if (sidebar) {
      structures[fName] = getStructure(sidebar);
    } else {
      structures[fName] = "Sidebar not found";
    }
  }
}

return structures;

async function wireAllPrototypesProperly() {
  const workspace = figma.getNodeById('8:2');
  await figma.setCurrentPageAsync(workspace);

  const f1 = workspace.children.find(c => c.name === "01_Dashboard");
  const f2 = workspace.children.find(c => c.name === "02_Timeline");
  const f3 = workspace.children.find(c => c.name === "03_Task_Board");
  const f4 = workspace.children.find(c => c.name === "04_Files");
  const f5 = workspace.children.find(c => c.name === "05_Settings");
  const f6 = workspace.children.find(c => c.name === "06_Messages");

  const framesMap = {
    "Dashboard": f1,
    "Timeline": f2,
    "Task": f3,
    "Files": f4,
    "Settings": f5,
    "Messages": f6
  };

  const results = [];
  const allFrames = [f1, f2, f3, f4, f5, f6];

  // Helper to search recursively for children with specified name
  function findChildByName(node, name) {
    if (node.name === name) return node;
    if ('children' in node) {
      for (const child of node.children) {
        const found = findChildByName(child, name);
        if (found) return found;
      }
    }
    return null;
  }

  for (const fr of allFrames) {
    const sidebar = fr.children.find(c => c.name === "Sidebar");
    if (!sidebar) {
      results.push(`No Sidebar in ${fr.name}`);
      continue;
    }

    const navItems = [
      { key: "Dashboard", name: "Nav_Dashboard" },
      { key: "Timeline", name: "Nav_Timeline" },
      { key: "Task", name: "Nav_Task" },
      { key: "Files", name: "Nav_Files" },
      { key: "Settings", name: "Nav_Settings" },
      { key: "Messages", name: "Nav_Messages" }
    ];

    for (const item of navItems) {
      const navBtn = findChildByName(sidebar, item.name);
      if (!navBtn) {
        results.push(`Btn ${item.name} not found in Sidebar of ${fr.name}`);
        continue;
      }

      const targetFrame = framesMap[item.key];
      if (targetFrame) {
        if (targetFrame.id === fr.id) {
          // Clear reaction or skip self
          continue;
        }
        try {
          navBtn.reactions = [{
            actions: [{
              type: "NODE",
              destinationId: targetFrame.id,
              navigation: "NAVIGATE",
              transition: null
            }],
            trigger: { type: "ON_CLICK" }
          }];
          results.push(`Connected ${fr.name} (${navBtn.name}) -> ${targetFrame.name}`);
        } catch (e) {
          results.push(`Failed ${fr.name} (${navBtn.name}) -> ${targetFrame.name}: ${e.message}`);
        }
      }
    }
  }

  return results;
}

return await wireAllPrototypesProperly();
